import{_ as a,o as e,c as i,a2 as n}from"./chunks/framework.DToEn73J.js";const g=JSON.parse('{"title":"成本与延迟优化","description":"","frontmatter":{"title":"成本与延迟优化","chapter":"6.4","order":4,"summary":"Prompt caching、批处理、投机执行与上下文精简对 Agent 单位成本的工程影响。"},"headers":[],"relativePath":"06-engineering-ops/cost-latency.md","filePath":"06-engineering-ops/cost-latency.md","lastUpdated":1788255095000}'),s={name:"06-engineering-ops/cost-latency.md"};function o(r,t,l,h,d,p){return e(),i("div",null,[...t[0]||(t[0]=[n(`<h1 id="成本与延迟优化" tabindex="-1">成本与延迟优化 <a class="header-anchor" href="#成本与延迟优化" aria-label="Permalink to &quot;成本与延迟优化&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>Agent 的单位成本 = 每次 LLM/检索调用的 token 数 × 单价，再乘以 Agent Loop 的步数。本页解决“如何在保持任务达成率的前提下，把单 run 的 token 与往返次数压到最低”。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ul><li><strong>Prompt Caching</strong>：把系统提示、Tool schema、稳定前缀标记为缓存段，命中后仅计缓存读取价（约为输入价的 1/10）。模板化 Prompt 是前提（见 6.1）。</li><li><strong>批处理</strong>：对非实时步骤（多候选评估、批量嵌入）走 batch API，折扣且削峰。</li><li><strong>投机执行（speculative tool calls）</strong>：在 LLM 输出首个 tool 调用意图时，并行预执行无副作用的只读 Tool（如检索、只读查询），缩短关键路径——需保证回滚与幂等。</li><li><strong>上下文精简</strong>：用 Context Window 预算调度，压缩历史、只回写必要 observation，避免重复喂入整段长文（见 3.2）。</li></ul><table tabindex="0"><thead><tr><th>手段</th><th>主要降本来源</th><th>风险</th></tr></thead><tbody><tr><td>Prompt Caching</td><td>复用稳定前缀</td><td>前缀变化即失效</td></tr><tr><td>批处理</td><td>离峰折扣</td><td>增加延迟</td></tr><tr><td>投机执行</td><td>缩短关键路径</td><td>冗余调用、副作用</td></tr><tr><td>上下文精简</td><td>减少 input token</td><td>丢上下文致失败</td></tr></tbody></table><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 最小：缓存标记 + 投机只读</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cache_control </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ephemeral&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 稳定前缀</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">speculate(read_only_tools, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">on</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">first_tool_intent)</span></span></code></pre></div><h2 id="为什么" tabindex="-1">为什么 <a class="header-anchor" href="#为什么" aria-label="Permalink to &quot;为什么&quot;">​</a></h2><p>不做成本工程，Agent 在长程任务上会凭空膨胀：每步都把整段对话塞回 Context Window，token 随步数线性增长，单 run 成本可能在 10 步内翻 3 倍。缓存 + 精简把增长从线性压到边际常量。</p><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li>投机执行对写操作也预跑，造成重复副作用（发两封邮件）。</li><li>只看 avg 延迟，忽视 p95——尾部延迟由超长上下文触发。</li></ul><h2 id="业界实现对照" tabindex="-1">业界实现对照 <a class="header-anchor" href="#业界实现对照" aria-label="Permalink to &quot;业界实现对照&quot;">​</a></h2><ul><li><strong>Anthropic Prompt Caching</strong>（<a href="https://docs.anthropic.com/en/docs/build-with-claude/prompt-caching%EF%BC%89%E3%80%82" target="_blank" rel="noreferrer">https://docs.anthropic.com/en/docs/build-with-claude/prompt-caching）。</a></li><li><strong>OpenAI Batch API</strong>（<a href="https://platform.openai.com/docs/guides/batch%EF%BC%89%E3%80%82" target="_blank" rel="noreferrer">https://platform.openai.com/docs/guides/batch）。</a></li><li><strong>Langfuse 成本看板</strong>（<a href="https://langfuse.com/docs%EF%BC%89%E3%80%82" target="_blank" rel="noreferrer">https://langfuse.com/docs）。</a></li></ul><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="/fk-ai-agent/03-context-memory/context-window">/03-context-memory/context-window</a></li><li><a href="/fk-ai-agent/04-planning-execution/model-routing">/04-planning-execution/model-routing</a></li><li><a href="/fk-ai-agent/06-engineering-ops/prompt-management">/06-engineering-ops/prompt-management</a></li><li><a href="/fk-ai-agent/03-context-memory/rag">/03-context-memory/rag</a></li></ul><hr><p><em>最后核实日期：2026-08-26</em></p>`,17)])])}const k=a(s,[["render",o]]);export{g as __pageData,k as default};
